pub proof fn reaching_backwards_never_terminates(reached: spec_fn(int) -> bool, start: int)
    requires
        reached(start),
        forall|step: int| #[trigger] reached(step) ==> reached(step + 1) && reached(step + 2),
    ensures
        reached(start - 1),
{
}

pub fn clamp_strictly_below_limit(value: u64, limit: u64) -> (result: u64)
    requires
        limit > 0,
    ensures
        result < limit,
{
    if value > limit {
        limit
    } else {
        value
    }
}

} // verus!
